#!/usr/bin/env node
// scripts/sync-site-screens.mjs
//
// Copies the SITE-FACING subset of docs/img/ (produced by `npm run screenshotter`, see
// docs/SCREENSHOTS.md and docs/screenshotter/apps/*.mjs) into site/assets/screens/, so the
// marketing site + docs manual stay self-contained — site/ is mirrored to vulos.org verbatim by
// the fleet-wide landing collector, so nothing outside site/ ever ships.
//
// This is deliberately NOT "copy everything in docs/img/": status-*.png, landing-hero*.png (the
// site's own hero — never re-embedded inside itself) and *-mobile.png (not regenerated by the
// current screenshotter drivers, so they're stale) are excluded. See MANIFEST below for the
// exact, explicit set — no glob, no pattern-guessing.
//
// Run directly:  node scripts/sync-site-screens.mjs
// Wired into:    npm run sync-site-screens
//                npm run screenshotter   (chained automatically — see package.json)
//
// Coverage guard: this is NOT a best-effort copy. It fails loudly and exits non-zero if:
//   - any manifest source file is missing from docs/img/,
//   - a dark/light pair is incomplete (one side present, the other missing),
//   - what actually lands in site/assets/screens/ doesn't exactly match what was expected.
// site/assets/screens/ is wiped and fully rewritten every run, so it can never silently drift
// from the manifest (e.g. an orphaned PNG left behind after a shot was renamed or dropped).
//
// This guard has been mutation-tested per the repo's standing rule that a guard you only read is
// not a guard: deleting an expected file and re-running this script must fail loudly and
// non-zero, not print PASS. See the commit that introduced this file for the paste of both runs.
//
// Page-weight step (site/ landing wave, 2026-07-31): docs/img/ shots come straight off a
// 2880x1800 Retina capture (~450-950 KB each, ~19 MB for the site-facing subset alone) — too
// heavy for a marketing page. Every file this script lands in site/assets/screens/ is
// downsized (max 1800px wide, never upscaled) and palette-quantized to 256 colours (PNG8 —
// these are flat UI screenshots, not photos; verified visually with no banding at that depth)
// via `magick`. If `magick` isn't on PATH, falls back to `sips -Z` (resize only, no palette
// step — bigger files, but still bounded) so this never hard-fails a machine without
// ImageMagick. Filenames and the coverage guard above are untouched by this — same names, same
// count, just lighter bytes.

import { readdirSync, existsSync, copyFileSync, mkdirSync, rmSync, statSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, '..');
const SRC = join(REPO_ROOT, 'docs', 'img');
const DEST = join(REPO_ROOT, 'site', 'assets', 'screens');

const MAX_WIDTH = 1800; // plenty for a 2x-retina-looking page shot at the widths this site uses

function optimizeImage(path) {
  try {
    execFileSync('magick', [path, '-resize', `${MAX_WIDTH}x>`, '-strip', '-colors', '256', `PNG8:${path}`], { stdio: 'ignore' });
    return 'magick';
  } catch (e) {
    try {
      execFileSync('sips', ['-Z', String(MAX_WIDTH), path], { stdio: 'ignore' });
      return 'sips';
    } catch (e2) {
      console.error(`sync-site-screens: WARNING — neither magick nor sips could run on ${path}; shipping the full-size, unoptimized copy.`);
      return null;
    }
  }
}

// ---- manifest -----------------------------------------------------------------------------
// One entry per view. `pair: true` entries expect BOTH `${base}-dark.png` and `${base}-light.png`
// in docs/img/ (override with darkFile/lightFile for an irregular name). `pair: false` entries
// are shots that are legitimately dark-only — a `reason` is required so an unpaired shot can
// never slip in silently.
const MANIFEST = [
  // ---- client app views ----
  { pair: true, base: 'mail' },
  { pair: true, base: 'chat' },
  { pair: true, base: 'files' },
  { pair: true, base: 'identity' },
  { pair: true, base: 'contacts' },
  { pair: true, base: 'calendar' },
  { pair: true, base: 'calendar-agenda' },
  { pair: true, base: 'groups' },
  { pair: true, base: 'settings' },
  { pair: true, base: 'compose' },
  { pair: true, base: 'inspector' },
  // path-graph's dark shot kept its pre-existing theme-less filename — site/index.html (owned by
  // a later wave, not renamed here) already hardcodes "assets/screens/path-graph.png".
  { pair: true, base: 'path-graph', darkFile: 'path-graph.png', lightFile: 'path-graph-light.png' },

  // ---- onboarding: dark-only. client/index.html hardcodes data-theme="dark" until the shell
  // mounts, so there is no real theme toggle to click during onboarding — this pipeline refuses
  // to fake a light variant with injected CSS, so these stay intentionally unpaired. ----
  { pair: false, file: 'onboarding-safety.png', reason: 'no theme toggle exists during onboarding (dark is hardcoded pre-shell)' },
  { pair: false, file: 'onboarding-identity.png', reason: 'no theme toggle exists during onboarding (dark is hardcoded pre-shell)' },

  // ---- management console ----
  { pair: true, base: 'console-overview' },
  { pair: true, base: 'console-members' },
  { pair: true, base: 'console-directory' },
  { pair: true, base: 'console-billing' },

  // ---- superadmin ----
  { pair: true, base: 'superadmin-overview' },
  { pair: true, base: 'superadmin-fleet' },
  { pair: true, base: 'superadmin-abuse' },
  { pair: true, base: 'superadmin-billing' },
];

function resolveExpected() {
  const expected = []; // { src, destName }
  const problems = [];
  for (const entry of MANIFEST) {
    if (entry.pair) {
      const darkFile = entry.darkFile || `${entry.base}-dark.png`;
      const lightFile = entry.lightFile || `${entry.base}-light.png`;
      const darkOk = existsSync(join(SRC, darkFile));
      const lightOk = existsSync(join(SRC, lightFile));
      if (!darkOk || !lightOk) {
        problems.push(
          `  [${entry.base}] incomplete pair — dark:${darkOk ? 'OK' : 'MISSING ' + darkFile} ` +
          `light:${lightOk ? 'OK' : 'MISSING ' + lightFile}`,
        );
        continue;
      }
      expected.push({ src: join(SRC, darkFile), destName: darkFile });
      expected.push({ src: join(SRC, lightFile), destName: lightFile });
    } else {
      if (!existsSync(join(SRC, entry.file))) {
        problems.push(`  [${entry.file}] MISSING (unpaired — ${entry.reason})`);
        continue;
      }
      expected.push({ src: join(SRC, entry.file), destName: entry.file });
    }
  }
  return { expected, problems };
}

function main() {
  const { expected, problems } = resolveExpected();

  if (problems.length) {
    console.error(
      `sync-site-screens: ${problems.length} manifest problem(s) — refusing to sync a partial ` +
      `set:\n${problems.join('\n')}`,
    );
    process.exit(1);
  }

  // Wipe and rewrite DEST every run so it can never silently drift from MANIFEST above.
  rmSync(DEST, { recursive: true, force: true });
  mkdirSync(DEST, { recursive: true });
  let bytesBefore = 0, bytesAfter = 0, magickCount = 0, sipsCount = 0, unoptimizedCount = 0;
  for (const { src, destName } of expected) {
    const destPath = join(DEST, destName);
    copyFileSync(src, destPath);
    bytesBefore += statSync(destPath).size;
    const via = optimizeImage(destPath);
    if (via === 'magick') magickCount++;
    else if (via === 'sips') sipsCount++;
    else unoptimizedCount++;
    bytesAfter += statSync(destPath).size;
  }

  // Coverage-count assertion, re-derived from the filesystem (not the in-memory `expected` array)
  // so a copy that silently no-oped can't slip through: what landed must exactly equal what was
  // expected — no more, no fewer, no substitutions.
  const landed = readdirSync(DEST).filter((f) => f.endsWith('.png'));
  const expectedNames = new Set(expected.map((e) => e.destName));
  const missing = [...expectedNames].filter((n) => !landed.includes(n));
  const extra = landed.filter((n) => !expectedNames.has(n));

  if (missing.length || extra.length || landed.length !== expectedNames.size) {
    console.error(
      `sync-site-screens: COVERAGE MISMATCH — expected ${expectedNames.size} file(s), found ` +
      `${landed.length} in ${DEST}\n` +
      (missing.length ? `  missing: ${missing.join(', ')}\n` : '') +
      (extra.length ? `  unexpected: ${extra.join(', ')}\n` : ''),
    );
    process.exit(1);
  }

  const pairedCount = MANIFEST.filter((e) => e.pair).length;
  const unpairedCount = MANIFEST.filter((e) => !e.pair).length;
  const mb = (n) => (n / (1024 * 1024)).toFixed(1);
  console.log(
    `sync-site-screens: OK — ${landed.length} file(s) synced into site/assets/screens/ ` +
    `(${pairedCount} paired view(s) × 2 themes, ${unpairedCount} intentionally-unpaired dark-only shot(s)).`,
  );
  console.log(
    `sync-site-screens: optimized ${magickCount} via magick, ${sipsCount} via sips fallback, ` +
    `${unoptimizedCount} unoptimized — ${mb(bytesBefore)} MB -> ${mb(bytesAfter)} MB.`,
  );
}

main();
